node retail.js | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{const R=s.trim().split("\n").filter(l=>l[0]=="{").map(JSON.parse);const sum=f=>R.reduce((a,r)=>a+f(r),0);const fr=k=>{const a=sum(r=>+r[k].split("/")[0]),b=sum(r=>+r[k].split("/")[1]);return a+"/"+b};console.log((process.env.P||"").padEnd(34),(process.env.NOEDH?"no data":"data").padEnd(8),"picks",String(sum(r=>r.app)).padStart(3),"B/M/A",R.map(r=>r.bma).join(" "),"| installed",sum(r=>r.installed.found)+"/25","| other",sum(r=>r.other.found)+"/111","| total",sum(r=>r.installed.found+r.other.found)+"/136","| tiers",fr("budget"),fr("mid"),fr("apex"),"| same slot",sum(r=>r.installed.sameSlot+r.other.sameSlot))})'
